export type PikachuAuthoredSmash = 'forward-smash' | 'up-smash' | 'down-smash';

export function buildPikachuSmashWithAuthoredHurtboxes(action: PikachuAuthoredSmash): AttackMoveWithAnimation {
  const rows = PIKACHU_SMASH_AUTHORED_HURTBOX_POSES.filter(row => row.action === action);
  const move = buildPikachuNormalMove(action, action === 'up-smash' ? pikachuUpSmashPose : undefined);
  const hurtboxModifiers: MoveHurtboxModifier[] = rows.flatMap(row => row.hurtboxes.map(hurtbox => ({
    frameWindow: { startFrame: row.startElapsed, endFrame: row.endElapsed }, replaceBody: true, hurtbox })));
  const startupEnd = move.startupFrames;
  const activeEnd = move.startupFrames + move.activeFrames;
  const startupFrames = rows.filter(row => row.startElapsed < startupEnd).length;
  const activeFrames = rows.filter(row => row.startElapsed >= startupEnd && row.startElapsed < activeEnd).length;
  return { ...move, hurtboxModifiers, animation: { startupFrames, activeFrames,
    recoveryFrames: rows.length - startupFrames - activeFrames,
    frameWindows: rows.map((row, artFrameIndex) => ({ startFrame: row.startElapsed, endFrame: row.endElapsed, artFrameIndex })) } };
}
